CitationCard: FC<CitationCardProps> = ({
  group,
  activeIndex,
  onIndexChange,
  onPreview,
  onOpenInBrowser,
  headerIcon,
  labels,
  typography,
  colors,
}) => {
  const total = group.annotations.length;
  const annotation = group.annotations[activeIndex] ?? group.primaryAnnotation;
  const hasSwitcher = total > 1;
  const sourceContentType =
    group.primaryAnnotation.body?.source?.attachment?.type;
  const isWebLink =
    onPreview == null ||
    sourceContentType === MIMEType.HTML ||
    sourceContentType === MIMEType.XHTML;

  const sourceNameClassName =
    typography?.sourceNameClassName ?? 'dial-tiny-text';
  const titleClassName = typography?.titleClassName ?? 'dial-body-semi-text';
  const quoteClassName = typography?.quoteClassName ?? 'dial-small-text';
  const quoteStrongClassName =
    typography?.quoteStrongClassName ?? 'dial-small-semi-text';
  const switcherClassName = typography?.switcherClassName ?? 'dial-tiny-text';

  const cssVars = buildCssVars({
    '--cc-card-bg': colors?.cardBackground,
    '--cc-quote-text': colors?.quoteText,
    '--cc-title-text': colors?.titleText,
    '--cc-switcher-text': colors?.switcherText,
    '--cc-source-name-text': colors?.sourceNameText,
  });

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={labels.ariaLabel}
      style={cssVars}
      className={mergeClasses(
        'flex w-[400px] flex-col gap-3 rounded-lg p-4 shadow-lg',
        styles.card,
        QUOTATIONS_CLASS.citationCard,
      )}
    >
      {/* Header */}
      <div className="flex items-center justify-between gap-2">
        <div className="flex min-w-0 items-center gap-1">
          {headerIcon}
          <EllipsisTooltip
            text={group.sourceName}
            className={mergeClasses(
              sourceNameClassName,
              'min-w-0',
              styles.sourceName,
            )}
          />
        </div>
        {hasSwitcher && (
          <div className="flex shrink-0 items-center gap-1">
            <GhostIconButton
              icon={
                <IconChevronLeft
                  size={14}
                  className="rtl:scale-x-[-1]"
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              size={ElementSize.Small}
              aria-label={labels.previousCitation}
              onClick={() => onIndexChange((activeIndex - 1 + total) % total)}
            />
            <span className={mergeClasses(switcherClassName, styles.switcher)}>
              {labels.formatSwitcherText(activeIndex + 1, total)}
            </span>
            <GhostIconButton
              icon={
                <IconChevronRight
                  size={14}
                  className="rtl:scale-x-[-1]"
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              size={ElementSize.Small}
              aria-label={labels.nextCitation}
              onClick={() => onIndexChange((activeIndex + 1) % total)}
            />
          </div>
        )}
      </div>

      {(annotation.body?.title || annotation.body?.quote || hasSwitcher) && (
        <div className="flex flex-col gap-3">
          {annotation.body?.title && (
            <p
              className={mergeClasses(
                titleClassName,
                styles.title,
                'break-words',
              )}
            >
              {annotation.body.title}
            </p>
          )}
          {(annotation.body?.quote || hasSwitcher) && (
            <div
              className={mergeClasses(
                quoteClassName,
                styles.quote,
                'line-clamp-6 break-words',
                hasSwitcher && 'min-h-[3lh]',
              )}
            >
              {annotation.body?.quote && (
                <MarkdownRenderer
                  content={annotation.body.quote}
                  classNames={{
                    p: mergeClasses(quoteClassName, styles.quote),
                    ul: mergeClasses(quoteClassName, 'ps-3'),
                    ol: mergeClasses(quoteClassName, 'ps-3'),
                    strong: quoteStrongClassName,
                  }}
                />
              )}
            </div>
          )}
        </div>
      )}

      {/* Footer */}
      <div className="flex justify-start gap-2">
        {onPreview && (
          <PrimaryButton
            label={labels.preview}
            size={ElementSize.Small}
            onClick={() => onPreview(annotation)}
          />
        )}
        <PrimaryButton
          label={isWebLink ? labels.openInBrowser : labels.download}
          size={ElementSize.Small}
          onClick={() => onOpenInBrowser(annotation)}
        />
      </div>
    </div>
  );
}

export interface CitationCardColors {
  /** Card background color. Fallback: `--bg-layer-raised`. */
  cardBackground?: string;
  /** Quoted excerpt text color. Fallback: `--text-secondary`. */
  quoteText?: string;
  /** Annotation title text color. Fallback: `--text-primary`. */
  titleText?: string;
  /** Pagination switcher text color. Fallback: `--text-secondary`. */
  switcherText?: string;
  /** Source name text color. Fallback: `--text-primary`. */
  sourceNameText?: string;
}

export interface CitationCardLabels {
  /** Dialog aria-label (already includes the source name). */
  ariaLabel: string;
  /** Accessible label for the "previous citation" button. */
  previousCitation: string;
  /** Accessible label for the "next citation" button. */
  nextCitation: string;
  /** Returns the switcher text given the 1-based current index and total count, e.g. `(1, 3) => "1 / 3"`. */
  formatSwitcherText: (current: number, total: number) => string;
  /** Label for the "Preview" button. */
  preview: string;
  /** Label for the "Open in browser" button. */
  openInBrowser: string;
  /** Label for the "Download" button. */
  download: string;
}

export interface CitationCardProps {
  /** The annotation group whose citations are displayed in this popup. */
  group: AnnotationGroup;
  /** Zero-based index into `group.annotations` for the currently shown citation. */
  activeIndex: number;
  /** Called when the user navigates to a different annotation within the group. */
  onIndexChange: (index: number) => void;
  /**
   * Called when the user clicks the "Preview" button. Omit when the group has
   * nothing previewable (e.g. reference-only chunks) — the "Preview" button is
   * hidden and the remaining button is always labelled "Open in browser".
   */
  onPreview?: (annotation: Annotation) => void;
  /** Called when the user clicks the "Open in browser"/"Download" button. */
  onOpenInBrowser: (annotation: Annotation) => void;
  /** Optional icon rendered before the source name in the card header. */
  headerIcon?: ReactNode;
  /** User-visible strings. */
  labels: CitationCardLabels;
  /** Optional typography class overrides. */
  typography?: CitationCardTypography;
  /** Optional color overrides. */
  colors?: CitationCardColors;
}

export interface CitationCardTypography {
  /** CSS class applied to the source name ellipsis. Defaults to `'dial-tiny-text'`. */
  sourceNameClassName?: string;
  /** CSS class applied to the annotation title. Defaults to `'dial-body-semi-text'`. */
  titleClassName?: string;
  /** CSS class applied to the quoted excerpt. Defaults to `'dial-small-text'`. */
  quoteClassName?: string;
  /** CSS class applied to bold spans inside the quoted excerpt. Defaults to `'dial-small-semi-text'` — the semibold step matching the default `quoteClassName`. */
  quoteStrongClassName?: string;
  /** CSS class applied to the pagination switcher text. Defaults to `'dial-tiny-text'`. */
  switcherClassName?: string;
}

CitationMarker: FC<CitationMarkerProps> = ({
  annotationCount,
  onOpen,
  icon,
  labels,
  labelClassName = 'dial-caption-text',
}) => (
  <NeutralButton
    size={ElementSize.Small}
    /*
     * A source name is server-supplied and routinely a full folder path plus a
     * page number, long enough to wrap at one of its hyphens. The pill is a
     * fixed 24px tall and centers its content, so a second line overflows it —
     * the marker stays one ellipsised line instead, capped so several markers
     * share a row. `min-w-0` is what lets the label shrink below its text
     * width; a flex item's `min-width: auto` would otherwise hold it open.
     * The full name remains in the card header and in `aria-label`.
     */
    className={mergeClasses('max-w-[240px]', QUOTATIONS_CLASS.citationMarker)}
    textClassName="min-w-0 truncate"
    iconBefore={icon}
    label={
      <span className={labelClassName}>
        {annotationCount > 1 ? labels.labelWithOverflow : labels.label}
      </span>
    }
    aria-label={labels.ariaLabel}
    onClick={onOpen}
  />
)

export interface CitationMarkerLabels {
  /** Accessible label for the marker button. */
  ariaLabel: string;
  /** Button text when `annotationCount === 1`. */
  label: string;
  /** Button text when `annotationCount > 1`. */
  labelWithOverflow: string;
}

export interface CitationMarkerProps {
  /** Human-readable source name derived from the attachment URL. */
  sourceName: string;
  /** Total number of annotations in this citation group. */
  annotationCount: number;
  /** Called when the user clicks the marker to open the citation popup. */
  onOpen: () => void;
  /** Optional icon rendered before the label; omitted by default. */
  icon?: ReactNode;
  /** User-visible strings. */
  labels: CitationMarkerLabels;
  /** Typography class applied to the marker's label text. Defaults to `'dial-caption-text'`. */
  labelClassName?: string;
}

CitationDropdown: FC<CitationDropdownProps> = ({
  group,
  onPreview,
  onOpenInBrowser,
  icon,
  headerIcon,
  cardLabels,
  markerLabels,
  cardTypography,
  markerLabelClassName,
}) => {
  const citationCard = useCitationCardContext();
  const ownerKey = useId();
  const isOpen = citationCard.isOpen(ownerKey);
  const activeIndex = citationCard.getActiveIndex(group.groupKey);

  const handleOpenChange = useCallback(
    (nextOpen: boolean) => {
      if (!nextOpen) citationCard.closePopup(ownerKey);
    },
    [citationCard, ownerKey],
  );

  const handlePreview = useMemo(
    () =>
      onPreview
        ? (annotation: Annotation) => {
            onPreview(annotation);
            citationCard.closePopup(ownerKey);
          }
        : undefined,
    [onPreview, citationCard, ownerKey],
  );

  /*
   * This is a controlled popover carrying an interactive card and needs
   * `bottom-end` so the 400px card aligns with the marker instead of
   * overhanging it. The resolved `Tooltip` export is the 2.0 component; it
   * narrows `placement` to the four `TooltipPlacement` sides, which cannot
   * express `-end` alignment, so no `placement` is passed here.
   */
  return (
    <Tooltip
      open={isOpen}
      onOpenChange={handleOpenChange}
      triggerClassName="ms-1 inline-flex align-middle"
      contentClassName={mergeClasses(
        '!p-0 !bg-transparent !border-0 !shadow-none !max-w-none !rounded-none',
        styles.content,
        QUOTATIONS_CLASS.citationDropdown,
      )}
      tooltip={
        <CitationCard
          group={group}
          activeIndex={activeIndex}
          onIndexChange={(i) => citationCard.setActiveIndex(group.groupKey, i)}
          onPreview={handlePreview}
          onOpenInBrowser={onOpenInBrowser}
          headerIcon={headerIcon}
          labels={cardLabels}
          typography={cardTypography}
        />
      }
    >
      <CitationMarker
        sourceName={group.sourceName}
        annotationCount={group.annotations.length}
        onOpen={() => citationCard.openPopup(ownerKey)}
        icon={icon}
        labels={markerLabels}
        labelClassName={markerLabelClassName}
      />
    </Tooltip>
  );
}

export interface CitationDropdownProps {
  /** The annotation group represented by this marker+popup pair. */
  group: AnnotationGroup;
  /**
   * Called when the user clicks "Preview" for an annotation. Omit when the
   * group has nothing previewable — the "Preview" button is hidden.
   */
  onPreview?: (annotation: Annotation) => void;
  /** Called when the user clicks "Open in browser" for an annotation. */
  onOpenInBrowser: (annotation: Annotation) => void;
  /** Optional icon rendered before the marker's label. */
  icon?: ReactNode;
  /** Optional icon rendered in the card header. When absent, no header icon is shown. */
  headerIcon?: ReactNode;
  /** User-visible strings for the card popup. */
  cardLabels: CitationCardLabels;
  /** User-visible strings for the inline marker button. */
  markerLabels: CitationMarkerLabels;
  /** Optional typography overrides forwarded to the card. */
  cardTypography?: CitationCardTypography;
  /** Typography class forwarded to the marker's label text. Defaults to `'dial-caption-text'`. */
  markerLabelClassName?: string;
}

useCitationCardContext = (): CitationCardHook => {
  const ctx = useContext(CitationCardContext);
  if (ctx == null)
    throw new Error(
      'useCitationCardContext must be used within a CitationCardProvider',
    );
  return ctx;
}

useAnnotations = (
  message: Message,
  isStreaming: boolean,
): Annotation[] => {
  return useMemo(() => {
    if (isStreaming) return [];
    return resolveMessageAnnotations(message);
  }, [isStreaming, message]);
}

useCitationCard = () => {
  const [state, setState] = useState<CitationCardState>(initialState);

  const openPopup = useCallback((ownerKey: string) => {
    setState((prev) => ({ ...prev, openOwnerKey: ownerKey }));
  }, []);

  const closePopup = useCallback((ownerKey: string) => {
    setState((prev) =>
      prev.openOwnerKey === ownerKey ? { ...prev, openOwnerKey: null } : prev,
    );
  }, []);

  const setActiveIndex = useCallback((groupKey: string, index: number) => {
    setState((prev) => ({
      ...prev,
      activeIndexByGroup: { ...prev.activeIndexByGroup, [groupKey]: index },
    }));
  }, []);

  return useMemo(
    () => ({
      openPopup,
      closePopup,
      setActiveIndex,
      isOpen: (ownerKey: string) => state.openOwnerKey === ownerKey,
      getActiveIndex: (groupKey: string) =>
        state.activeIndexByGroup[groupKey] ?? 0,
    }),
    [openPopup, closePopup, setActiveIndex, state],
  );
}

useCitationMarkdownComponents = (
  content: string,
  groups: AnnotationGroup[],
  callbacks: UseCitationMarkdownComponentsCallbacks,
  isStreaming = false,
  isCompactTypography = false,
): { processedContent: string; markdownComponents: Components } => {
  const { onPreview, onOpenInBrowser, buildLabels } = callbacks;

  const processedContent = useMemo(() => {
    if (isStreaming) return stripCitTagsWhileStreaming(content);
    const contentWithSentinels =
      groups.length > 0 ? injectCitationSentinels(content, groups) : content;
    return escapeUnsupportedCitTags(contentWithSentinels);
  }, [content, groups, isStreaming]);

  const hasCitElement = processedContent.includes('<cit');

  const markdownComponents = useMemo((): Components => {
    const citGroupsByTagId = new Map<string, AnnotationGroup>();
    for (const group of groups) {
      const tagId = citTagId(group);
      if (tagId != null) citGroupsByTagId.set(tagId, group);
    }

    const renderGroup = (group: AnnotationGroup) => {
      const { cardLabels, markerLabels } = buildLabels(group);

      return (
        <CitationDropdown
          key={`citation-${group.groupKey}`}
          group={group}
          onPreview={(annotation) => onPreview(annotation, group)}
          onOpenInBrowser={onOpenInBrowser}
          cardLabels={cardLabels}
          markerLabels={markerLabels}
        />
      );
    };

    const renderMarker = (idx: number) => {
      const group = groups[idx];
      return group ? renderGroup(group) : null;
    };

    /*
     * `cit` isn't a known JSX intrinsic element, hence the cast — `data-id`
     * (not `id`) is the lookup attribute because `rehype-sanitize`'s default
     * schema prefixes `id`/`name` with `user-content-` to prevent DOM
     * clobbering; `data-*` attributes are exempt. A tag id with no matching
     * group (annotation never arrived, or doesn't resolve) is serialized back
     * to literal text rather than disappearing.
     */
    const citComponent = {
      cit: (props: { 'data-id'?: string; children?: ReactNode }) => {
        const group =
          props['data-id'] != null
            ? citGroupsByTagId.get(props['data-id'])
            : undefined;
        return group
          ? renderGroup(group)
          : renderCitTagAsText(props['data-id'], props.children);
      },
    } as Components;

    if (groups.length === 0) {
      return hasCitElement ? citComponent : {};
    }

    return {
      ...citComponent,
      p: ({ children, ...rest }) => (
        <p
          {...rest}
          className={mergeClasses(
            isCompactTypography
              ? 'dial-small-paragraph-text'
              : 'dial-body-paragraph-text',
            'mb-3 [overflow-wrap:anywhere] [text-wrap:pretty] last:mb-0',
          )}
        >
          {replaceSentinelsInChildren(children, renderMarker)}
        </p>
      ),
      li: ({ children, ...rest }) => (
        <li {...rest} className="mb-1.5 last:mb-0">
          {replaceSentinelsInChildren(children, renderMarker)}
        </li>
      ),
    };
  }, [
    groups,
    onPreview,
    onOpenInBrowser,
    buildLabels,
    isCompactTypography,
    hasCitElement,
  ]);

  return { processedContent, markdownComponents };
}

export interface UseCitationMarkdownComponentsCallbacks {
  /** Called when a citation marker's preview action is invoked, with the clicked annotation and its group. */
  onPreview(annotation: Annotation, group: AnnotationGroup): void;
  /** Called when a citation marker's open-in-browser action is invoked. */
  onOpenInBrowser(annotation: Annotation): void;
  /** Builds the translated label bundles used by a given citation group's card and marker. */
  buildLabels(group: AnnotationGroup): {
    cardLabels: CitationCardLabels;
    markerLabels: CitationMarkerLabels;
  };
}

gatherSameSourceAnnotations = (
  clicked: Annotation,
  annotations: Annotation[],
): Annotation[] => {
  const url = clicked.body?.source?.attachment?.url;
  if (url == null || !annotations.includes(clicked)) return [clicked];

  return annotations.filter((a) => a.body?.source?.attachment?.url === url);
}

groupAnnotations = (
  annotations: Annotation[],
): AnnotationGroup[] => [
  ...groupAnnotationsByCitId(annotations),
  ...groupAnnotationsBySource(annotations),
]

groupAnnotationsByCitId = (
  annotations: Annotation[],
): AnnotationGroup[] => {
  const map = new Map<string, AnnotationGroup>();

  for (const annotation of annotations) {
    const id = getHtmlTagSelector(annotation)?.id;
    if (id == null) continue;
    const url = annotation.body?.source?.attachment?.url;
    if (url == null) continue;

    const existing = map.get(id);
    if (existing) {
      existing.annotations.push(annotation);
    } else {
      map.set(id, {
        groupKey: `cit:${id}`,
        sourceUrl: url,
        sourceName: resolveSourceName(annotation, url),
        annotations: [annotation],
        primaryAnnotation: annotation,
      });
    }
  }

  return Array.from(map.values());
}

groupAnnotationsBySource = (
  annotations: Annotation[],
): AnnotationGroup[] => {
  const map = new Map<string, AnnotationGroup>();

  for (const annotation of annotations) {
    if (isHtmlTagAnnotation(annotation)) continue;
    const url = annotation.body?.source?.attachment?.url;
    if (url == null) continue;

    const existing = map.get(url);
    if (existing) {
      existing.annotations.push(annotation);
    } else {
      map.set(url, {
        groupKey: url,
        sourceUrl: url,
        sourceName: resolveSourceName(annotation, url),
        annotations: [annotation],
        primaryAnnotation: annotation,
      });
    }
  }

  return Array.from(map.values());
}

export interface AnnotationGroup {
  /**
   * This group's identity — used for open/active-index popup state and
   * React keys. Equals `sourceUrl` for a `groupAnnotationsBySource` group;
   * equals `` `cit:${id}` `` for a `groupAnnotationsByCitId` group, so two
   * cit ids citing the same document never share popup state.
   */
  groupKey: string;
  /** The cited attachment's URL — used for Preview/Download. */
  sourceUrl: string;
  /**
   * Human-readable name derived from the URL: the last non-empty path segment
   * (decoded, without query params) when available, otherwise the URL hostname.
   */
  sourceName: string;
  /** Every annotation in this group, in their original order. */
  annotations: Annotation[];
  /** The first annotation in the group — used for the inline citation marker position. */
  primaryAnnotation: Annotation;
}

annotationsToPdfHighlights = (
  annotations: Annotation[],
): InputHighlightData[] =>
  annotations.flatMap((annotation, i) => {
    const selector = annotation.body?.selector;
    if (selector == null) return [];

    const selectors = Array.isArray(selector) ? selector : [selector];
    const bboxes = selectors.flatMap((s) => {
      if (!isAnnotationSelector(s)) return [];
      const box = readPdfSelectorBox(s);
      return box != null ? [box] : [];
    });

    if (bboxes.length === 0) return [];
    return [
      {
        id: annotationHighlightId(annotation, i),
        bboxes,
        style: CITATION_HIGHLIGHT_STYLE,
      },
    ];
  })

annotationToOfficeHighlightLocations = (
  annotation: Annotation,
): OfficeHighlightLocation[] => {
  const selector = annotation.body?.selector;
  if (selector == null) return [];
  const selectors = Array.isArray(selector) ? selector : [selector];

  return selectors.flatMap((s): OfficeHighlightLocation[] => {
    if (!isAnnotationSelector(s)) return [];

    if (isDocxRangeSelector(s)) {
      const location = normalizeDocxSelector(s);
      return location ? [location] : [];
    }
    if (isPptxRangeSelector(s)) {
      const location = normalizePptxSelector(s);
      return location ? [location] : [];
    }
    if (isExcelRcRangeSelector(s)) {
      const location = normalizeExcelSelector(s);
      return location ? [location] : [];
    }
    const tableRow = normalizeOfficeTableAnchor(s);
    return tableRow ? [tableRow] : [];
  });
}

getAnnotationPdfPage = (
  annotation: Annotation,
): number | undefined => {
  const selector = annotation.body?.selector;
  if (selector == null) return undefined;

  const selectors = Array.isArray(selector) ? selector : [selector];
  for (const s of selectors) {
    if (!isAnnotationSelector(s)) continue;
    const box = readPdfSelectorBox(s);
    if (box != null) return box.page;
  }
  return undefined;
}

isDocxRangeSelector = (
  selector: AnnotationSelector,
): selector is DocxRangeSelector => {
  if (selector.type !== 'docx_text_range') return false;
  const s = selector as Record<string, unknown>;
  return (
    typeof s['story'] === 'string' &&
    Array.isArray(s['path']) &&
    (s['path'] as unknown[]).every((segment) => typeof segment === 'number') &&
    typeof s['start'] === 'number' &&
    typeof s['end'] === 'number' &&
    typeof s['text'] === 'string'
  );
}

isExcelRcRangeSelector = (
  selector: AnnotationSelector,
): selector is ExcelRcRangeSelector => {
  if (selector.type !== 'excel_rc_range') return false;
  const s = selector as Record<string, unknown>;
  return (
    typeof s['sheet'] === 'string' &&
    isCellAddressLike(s['start']) &&
    (s['end'] === undefined || s['end'] === null || isCellAddressLike(s['end']))
  );
}

isPptxRangeSelector = (
  selector: AnnotationSelector,
): selector is PptxRangeSelector => {
  if (selector.type !== 'pptx_text_range') return false;
  const s = selector as Record<string, unknown>;
  return (
    typeof s['slide'] === 'number' &&
    typeof s['shape_id'] === 'string' &&
    typeof s['start'] === 'number' &&
    typeof s['end'] === 'number' &&
    typeof s['text'] === 'string'
  );
}

resolveMessageAnnotations = (message: Message): Annotation[] => {
  const contentAnnotations = message.custom_content?.annotations;
  if (contentAnnotations?.length) {
    return contentAnnotations
      .filter(
        (a): a is Annotation =>
          a != null && a.body?.source?.attachment?.url != null,
      )
      .map(normalizePersistedHtmlTagAttachmentType);
  }

  const customFields = (message as Record<string, unknown>)['custom_fields'];
  if (typeof customFields !== 'object' || customFields === null) return [];
  const raw = (customFields as Record<string, unknown>)['annotations'];
  if (!Array.isArray(raw) || raw.length === 0) return [];

  return normalizeRawAnnotations(
    raw,
    message.custom_content?.attachments ?? [],
  ).map(normalizePersistedHtmlTagAttachmentType);
}

