injectCitationSentinels = (
  content: string,
  groups: AnnotationGroup[],
): string => {
  const positions = groups
    .map((g, idx) => ({ g, idx }))
    .filter(
      ({ g }) => g.primaryAnnotation.target?.selector?.type !== 'html_tag',
    )
    .map(({ g, idx }) => {
      const selector = g.primaryAnnotation.target?.selector;
      const end =
        selector != null &&
        typeof selector === 'object' &&
        'type' in selector &&
        selector.type === 'text_character_range'
          ? (selector as TextCharacterRangeSelector).end
          : content.length;
      return { idx, pos: Math.min(end, content.length) };
    })
    .sort((a, b) => b.pos - a.pos);

  let result = content;
  for (const { idx, pos } of positions) {
    result = `${result.slice(0, pos)}⟦C${idx}⟧${result.slice(pos)}`;
  }
  return result;
}

replaceSentinelsInChildren = (
  children: ReactNode,
  renderMarker: (idx: number) => ReactNode,
): ReactNode => {
  if (typeof children === 'string') {
    const parts = children.split(SENTINEL_RE);
    if (parts.length === 1) return children;

    const result: ReactNode[] = [];
    parts.forEach((part, i) => {
      if (i % 2 === 1) {
        // Odd indices are the captured group (the idx digit string)
        result.push(renderMarker(parseInt(part, 10)));
      } else if (part) {
        result.push(part);
      }
    });
    return result;
  }

  if (Array.isArray(children)) {
    // React renders arrays natively — no Fragment wrapper needed
    return (children as ReactNode[]).flatMap((child) => {
      const replaced = replaceSentinelsInChildren(child, renderMarker);
      return Array.isArray(replaced) ? replaced : [replaced];
    });
  }

  return children;
}

stripCitTagsWhileStreaming = (content: string): string => {
  return escapeUnsupportedCitTags(content).replace(CIT_ELEMENT_RE, '');
}

parsePdfPageReference = (url: string): PdfPageReference | null => {
  const match = PDF_PAGE_REFERENCE_REGEX.exec(url);
  if (!match) return null;
  return {
    baseUrl: match[1],
    page: match[2] != null ? Number(match[2]) : null,
  };
}

getReferenceAttachmentGroups = (
  dtos: MessageAttachment[] | undefined,
): AnnotationGroup[] => {
  const annotations: Annotation[] = (dtos ?? [])
    .filter(isReferenceOnlyAttachment)
    .map((dto) => {
      const referenceUrl = dto.reference_url as string;
      const isPdfPage = parsePdfPageReference(referenceUrl) != null;
      return {
        body: {
          // omitted: dto.title already appears as the popup header (sourceName)
          quote: dto.data,
          source: {
            type: 'attachment' as const,
            attachment: {
              type: isPdfPage
                ? MIMEType.PDF
                : (dto.reference_type ?? dto.type ?? ''),
              url: referenceUrl,
              title: dto.title,
            },
          },
        },
      };
    });

  return groupAnnotationsBySource(annotations);
}

export interface PdfPageReference {
  /** The PDF file URL/id with the `#page=` fragment stripped. */
  baseUrl: string;
  /** 1-based page number, or `null` when the reference has no page fragment. */
  page: number | null;
}

